import React, { useState, useEffect } from "react";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";
import "./AdminDashboard.css";

export default function AdminDashboard() {
  const [selectedBranch, setSelectedBranch] = useState(null);
  const [branchAttendance, setBranchAttendance] = useState([]);
  const [loading, setLoading] = useState(false);
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  const branches = ["Hitech City", "Vanasthalipuram", "Nagole"];

  useEffect(() => {
    if (localStorage.getItem("role") !== "admin") {
      window.location.href = "/";
    }
  }, []);

  const fetchBranchAttendance = async (branch) => {
    setLoading(true);
    setSelectedBranch(branch);
    try {
      const res = await fetch(`http://localhost:5000/api/attendance/branch/${encodeURIComponent(branch)}`);
      if (!res.ok) throw new Error("Failed to fetch attendance");
      const data = await res.json();
      setBranchAttendance(data);
    } catch (err) {
      alert("Failed to load branch attendance");
      console.error(err);
      setBranchAttendance([]);
    } finally {
      setLoading(false);
    }
  };

  const viewFullAttendance = (employee) => {
    const params = new URLSearchParams({
      userId: employee.userId,
      name: employee.name,
      designation: employee.designation || "N/A",
      branch: selectedBranch
    });

    window.location.href = `/attendance-details?${params.toString()}`;
  };

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/";
  };

  const generateDateRange = (start, end) => {
    const dates = [];
    const current = new Date(start);
    while (current <= end) {
      dates.push(new Date(current).toISOString().split("T")[0]);
      current.setDate(current.getDate() + 1);
    }
    return dates;
  };

  const handleExport = async () => {
    if (!fromDate || !toDate) {
      alert("Please select a date range");
      return;
    }

    const start = new Date(fromDate);
    const end = new Date(toDate);
    if (start > end) {
      alert("Invalid date range");
      return;
    }

    // Calculate total working days (exclude weekends)
    let workingDays = 0;
    const tempDate = new Date(start);
    while (tempDate <= end) {
      const day = tempDate.getDay();
      if (day !== 0 && day !== 6) workingDays++;
      tempDate.setDate(tempDate.getDate() + 1);
    }

    setLoading(true);
    try {
      const employees = branchAttendance;
      const allData = await Promise.all(
        employees.map(async (emp) => {
          const res = await fetch(`http://localhost:5000/api/attendance/${emp.userId}`);
          if (!res.ok) throw new Error("Failed to fetch");
          const data = await res.json();

          // Filter records in range
          const rangeRecords = data.filter(
            (rec) => rec.date >= fromDate && rec.date <= toDate
          );

          const recordMap = new Map(rangeRecords.map((r) => [r.date, r]));

          let presents = 0;
          let lates = 0;

          const allDates = generateDateRange(start, end);

          allDates.forEach((dateStr) => {
            const rec = recordMap.get(dateStr);
            if (!rec || !rec.checkIn || !rec.checkOut) return; // Absent

            // Parse times (HH:MM:SS)
            const checkInParts = rec.checkIn.split(":").map(Number);
            const checkInHrs = checkInParts[0] + checkInParts[1] / 60 + checkInParts[2] / 3600;

            const checkOutParts = rec.checkOut.split(":").map(Number);
            const checkOutHrs = checkOutParts[0] + checkOutParts[1] / 60 + checkOutParts[2] / 3600;

            const lateHrs = Math.max(0, checkInHrs - 9.25); // Late after 9:15 AM
            const earlyHrs = Math.max(0, 18.5 - checkOutHrs); // Early before 6:30 PM

            const isHalfDay = lateHrs > 2 || earlyHrs > 2;

            presents += isHalfDay ? 0.5 : 1;

            if (lateHrs > 0) lates += 1;
          });

          return {
            Name: emp.name,
            ID: emp.userId,
            "Date Range": `${fromDate} to ${toDate}`,
            "Total Working Days": workingDays,
            "No of Presents": presents,
            "No of Lates": lates,
          };
        })
      );

      // Create Excel
      const worksheet = XLSX.utils.json_to_sheet(allData);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Attendance Summary");

      const excelBuffer = XLSX.write(workbook, { bookType: "xlsx", type: "array" });
      const blob = new Blob([excelBuffer], { type: "application/octet-stream" });
      saveAs(blob, `${selectedBranch}_Attendance_${fromDate}_to_${toDate}.xlsx`);
    } catch (err) {
      console.error(err);
      alert("Failed to export data");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="admin-dashboard">
      <div className="admin-header">
        <h1>Admin Dashboard - Attendance Overview</h1>
        <button className="logout-btn" onClick={handleLogout}>Logout</button>
      </div>

      {/* Branch Cards */}
      <div className="branches-grid">
        {branches.map((branch) => (
          <div
            key={branch}
            className={`branch-card ${selectedBranch === branch ? "active" : ""}`}
            onClick={() => fetchBranchAttendance(branch)}
          >
            <h3>{branch}</h3>
            <p>Click to view today's attendance</p>
          </div>
        ))}
      </div>

      {/* Branch Attendance Table */}
      {selectedBranch && (
        <div className="attendance-section">
          <h2>Today's Attendance - {selectedBranch}</h2>
          <p><strong>Date:</strong> {new Date().toLocaleDateString()}</p>

          {/* Export Section */}
          <div className="export-section">
            <label>From Date:</label>
            <input
              type="date"
              value={fromDate}
              onChange={(e) => setFromDate(e.target.value)}
            />
            <label>To Date:</label>
            <input
              type="date"
              value={toDate}
              onChange={(e) => setToDate(e.target.value)}
            />
            <button
              onClick={handleExport}
              disabled={!fromDate || !toDate || loading}
            >
              Export to Excel
            </button>
          </div>

          {loading ? (
            <p>Loading attendance data...</p>
          ) : branchAttendance.length === 0 ? (
            <p>No employees or attendance data for this branch today.</p>
          ) : (
            <table className="branch-attendance-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>ID</th>
                  <th>Designation</th>
                  <th>Status</th>
                  <th>Check In</th>
                  <th>Check Out</th>
                  <th>Hours</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {branchAttendance.map((emp) => (
                  <tr key={emp.userId} className={emp.status === "Absent" ? "absent-row" : ""}>
                    <td>{emp.name}</td>
                    <td>{emp.userId}</td>
                    <td>{emp.designation}</td>
                    <td>
                      <span className={`status-badge status-${emp.status.toLowerCase().replace(" ", "-")}`}>
                        {emp.status}
                      </span>
                    </td>
                    <td>{emp.checkIn}</td>
                    <td>{emp.checkOut}</td>
                    <td>{emp.hours}</td>
                    <td>
                      <button
                        className="view-full-btn"
                        onClick={() => viewFullAttendance(emp)}
                      >
                        Full History
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}
